node --input-type=module <<'NODE'
import * as esbuild from 'esbuild';import fs from 'node:fs';import crypto from 'node:crypto';
const sha=b=>crypto.createHash('sha256').update(b).digest('hex'),a=JSON.parse(fs.readFileSync('docs/remediation/evidence/W26.02/artifact.json')),w=JSON.parse(fs.readFileSync('docs/remediation/evidence/W26.02/worker.json'));
const version=fs.readFileSync('src/sdk/version.ts','utf8').match(/'([^']+)'/)[1];
const common={bundle:true,platform:'browser',target:'es2022',minify:false,sourcemap:false,legalComments:'none',logLevel:'silent',metafile:true,write:false,banner:{js:`/* edge-personalization SDK v${version} — one package: core (identity, transport), emit (four capture paths), listen (decisions). */`}};
const results=[];
for(const [entry,path,format] of [['src/sdk/index.ts','public/sdk/edge-personalization.esm.js','esm'],['src/sdk/browser.ts','public/sdk/edge-personalization.js','iife']]){
 const result=await esbuild.build({...common,entryPoints:[entry],outfile:path,format}),bytes=result.outputFiles[0].contents,current=fs.readFileSync(path),expected=w.bundle_generation.final.artifacts.find(x=>x.path===path),inputs=Object.keys(result.metafile.inputs);
 results.push({path,bytes:bytes.length,sha256:sha(bytes),exact_current:Buffer.from(bytes).equals(current),exact_worker:sha(bytes)===expected.sha256&&bytes.length===expected.bytes,inputs,exact_worker_inputs:JSON.stringify(inputs)===JSON.stringify(expected.inputs),all_inputs_pinned:inputs.every(p=>a.files.some(x=>x.path===p&&x.sha256===sha(fs.readFileSync(p))))});
}
console.log(JSON.stringify({at:new Date().toISOString(),write:false,esbuild_version:esbuild.version,results},null,2));
if(results.some(x=>!x.exact_current||!x.exact_worker||!x.exact_worker_inputs||!x.all_inputs_pinned))process.exitCode=1;
NODE

signature_check.command:
node - <<'NODE'
const fs=require('fs'),crypto=require('crypto');const w=JSON.parse(fs.readFileSync('docs/remediation/evidence/W26.02/worker.json')),b=JSON.parse(fs.readFileSync('docs/remediation/design/W26.02/baseline-v2.json'));function sig(text){let file='';const out=[];for(const line of text.split('\n')){if(line.startsWith('/'))file=line.trim();const m=line.match(/^\s+\d+:\d+\s+(warning|error)\s+(.+?)\s{2,}(\S+)\s*$/);if(m)out.push([file,m[1],m[2].trim(),m[3]].join('|'));}return out.sort();}const baseline=sig(b.baseline_static.captures.map(c=>c.output).join(''));const results=['static2','static3','static4'].map(k=>{const c=w.command_captures[k],s=sig(c.captures.map(c=>c.output).join(''));return{command:k,exit_code:c.exit_code,drained:c.drained,warnings:s.length,exact_baseline_signatures:JSON.stringify(s)===JSON.stringify(baseline),signature_sha256:crypto.createHash('sha256').update(JSON.stringify(s)).digest('hex')};});console.log(JSON.stringify({at:new Date().toISOString(),fresh_static_invocations:0,baseline_warnings:baseline.length,results},null,2));if(baseline.length!==107||results.some(x=>!x.exact_baseline_signatures||x.exit_code!==0||!x.drained))process.exit(1);
NODE
